/**
 * Declarative golden-probe matrix (SYNTHETIC identities from
 * platform/src/fixtures/synthetic-world.ts; not real people, not PHI).
 *
 * Expectations are DECLARED INTENT, written independently of the Rego:
 *  - every base case states whether it is allowed and with which reasons;
 *  - every perturbation (expired session, kill switch, consent, risk flag,
 *    assurance, role, relationships, verification secret...) states the deny
 *    reasons it causes and which action traits it applies to;
 *  - action traits (protected, mutation, consent-exempt, relationship-bound,
 *    minimum assurance) are declared here, not read from the catalogue.
 * Only field masks / allow-obligations (what an allowed decision returns) and
 * the intent/integration ids used to engage kill switches are read from the
 * catalogue; changing those still changes probes.json, so the expansion gate
 * sees it (FIELD_MASK_WIDENED, OBLIGATION_REMOVED, PROBE_INPUT_CHANGED).
 */
import { DELEGATIONS, ORGANIZATIONS, OTHER_TENANT_ID, PEOPLE, STAFF, TENANT_ID } from "../fixtures/synthetic-world.js";
import type { RelationshipFact, StaffRole } from "../protocol/index.js";
import type { PolicyInput } from "../protocol/policy.js";
import type { PolicyCatalogue } from "./catalogue.js";
import type { ConsoleDecisionInput } from "./console.js";
import type { GoldenExpectation, GoldenProbe, GoldenProbeFile } from "./golden.js";

export const GOLDEN_NOW = "2026-10-17T15:00:00.000Z";
const LATER = "2026-10-17T15:30:00.000Z";
const EARLIER = "2026-10-17T14:59:59.000Z";
const DIGEST_A = "a".repeat(64);
const DIGEST_B = "b".repeat(64);
export const GOLDEN_LABEL = "SYNTHETIC golden decision probes (LOCAL FIXTURE identities). Generated by platform/src/policy/golden-generate.ts; do not edit by hand.";
export const GOLDEN_GENERATOR = "platform/src/policy/golden-generate.ts";

const HUMAN_REASONS = new Set(["AUTHORIZATION_EXPIRED", "CONSENT_DECLINED_ALTERNATIVE_ROUTE", "CUSTODY_DISPUTE", "HIGH_RISK_HUMAN_ONLY", "HUMAN_BOUNDARY", "MINOR_CONFIDENTIALITY_REVIEW", "RISK_VERIFICATION_ABUSE"]);
const STEP_UP_REASONS = new Set(["STEP_UP_DIGEST_MISMATCH", "STEP_UP_EXPIRED", "STEP_UP_REQUIRED"]);

type Auth = PolicyInput["auth"];
type Resource = PolicyInput["resource"];

// ---------------------------------------------------------------- builders ----

function auth(actorId: string | null, role: Auth["selectedRole"], subjectId: string | null, organizationId: string | null, assurance: Auth["assurance"]): Auth {
  return {
    tenantId: TENANT_ID,
    sessionGeneration: 1,
    actorId,
    selectedRole: role,
    subjectId,
    organizationId,
    permittedScopes: [],
    assurance,
    authenticatedAt: actorId === null ? null : "2026-10-17T14:55:00.000Z",
    expiresAt: LATER,
    revoked: false,
    riskFlags: [],
    consentRecording: "GRANTED",
    consentAutomatedProcessing: "GRANTED",
    stepUpDigest: null,
    stepUpExpiresAt: null,
  };
}

const anonAuth = (): Auth => auth(null, null, null, null, "A0");

function resource(type: string, subjectId: string | null, organizationId: string | null, classification: Resource["classification"], actionDigest: string | null = null): Resource {
  return { type, tenantId: TENANT_ID, subjectId, organizationId, classification, actionDigest };
}

function fact(type: RelationshipFact["type"], actorId: string, subjectId: string | null, organizationId: string | null, scopes: string[], source: RelationshipFact["source"], extra: Partial<RelationshipFact> = {}): RelationshipFact {
  return { type, actorId, subjectId, organizationId, scopes, source, validUntil: null, constraints: [], ...extra };
}

