function req(action: string, purpose: PolicyInput["purpose"], a: Auth, r: Resource, relationships: RelationshipFact[], tool: PolicyInput["tool"] = null): PolicyInput {
  return { action, purpose, environment: "local", now: GOLDEN_NOW, tool, auth: a, resource: r, relationships, killSwitches: { ...KS_OFF } };
}

