// ------------------------------------------------------------ action traits ----

/** Declared intent per base case; see file header. */
interface Traits {
  alwaysAvailable: boolean;
  /** Request touches a specific person's or organization's records (risk flags, role required). */
  protected: boolean;
  /** Still allowed after the caller declined recording / automated processing. */
  consentExempt: boolean;
  /** Prepare/commit mutation: writes kill switch and safety mode deny it. */
  mutation: boolean;
  /** Needs an authoritative relationship fact. */
  relationship: boolean;
  minAssurance: "A0" | "A2";
}

const EXEMPT: Traits = { alwaysAvailable: true, protected: false, consentExempt: true, mutation: false, relationship: false, minAssurance: "A0" };
const OPEN_PUBLIC: Traits = { alwaysAvailable: false, protected: false, consentExempt: true, mutation: false, relationship: false, minAssurance: "A0" };
const OPEN_VERIFY: Traits = { ...OPEN_PUBLIC, consentExempt: false };
const PROTECTED_READ: Traits = { alwaysAvailable: false, protected: true, consentExempt: false, mutation: false, relationship: true, minAssurance: "A2" };
const MUTATION: Traits = { ...PROTECTED_READ, mutation: true };
const PROTECTED_INTAKE: Traits = { ...PROTECTED_READ, consentExempt: true };

interface BaseCase {
  key: string;
  description: string;
  tags: string[];
  traits: Traits;
  input: PolicyInput;
  allowReasons: string[];
}

