// ------------------------------------------------------------------ generate ----

function obligationsForDeny(reasons: readonly string[]): string[] {
  const out = new Set<string>();
  for (const r of reasons) {
    if (HUMAN_REASONS.has(r)) out.add("REQUIRE_HUMAN");
    if (STEP_UP_REASONS.has(r)) out.add("REQUIRE_STEP_UP");
  }
  return [...out].sort();
}

function authzExpectation(catalogue: PolicyCatalogue, action: string, e: { allow: true; reasons: string[] } | { allow: false; reasons: string[] }): GoldenExpectation {
  if (e.allow) {
    const def = catalogue.actions[action];
    if (!def) throw new Error(`golden matrix: allowed probe for uncatalogued action ${action}`);
    return { allow: true, reasonCodes: [...e.reasons].sort(), fieldMask: [...def.fieldMask].sort(), obligations: [...new Set(def.obligations)].sort() };
  }
  return { allow: false, reasonCodes: [...e.reasons].sort(), fieldMask: [], obligations: obligationsForDeny(e.reasons) };
}

function consoleExpectation(catalogue: PolicyCatalogue, action: string, e: { allow: boolean; reasons: string[] }): GoldenExpectation {
  if (!e.allow) return { allow: false, reasonCodes: [...e.reasons].sort(), fieldMask: [], obligations: ["AUDIT_ADMIN_ACTION"] };
  const def = catalogue.console.actions[action];
  if (!def) throw new Error(`golden matrix: allowed console probe for uncatalogued action ${action}`);
  const obligations = new Set<string>([...def.obligations, "AUDIT_ADMIN_ACTION"]);
  if (def.requiresBreakGlass) obligations.add("BREAK_GLASS_REVIEW");
  return { allow: true, reasonCodes: [...e.reasons].sort(), fieldMask: [], obligations: [...obligations].sort() };
}

const uniqTags = (...lists: string[][]): string[] => [...new Set(lists.flat())].slice(0, 8);

/** Generates every probe from the declarative matrix. Deterministic. */
export function generateProbes(catalogue: PolicyCatalogue): GoldenProbe[] {
  const probes: GoldenProbe[] = [];
  for (const base of BASES) {
    probes.push({ id: `authz.${base.key}.base`, entrypoint: "authz", description: base.description, tags: base.tags, expected: authzExpectation(catalogue, base.input.action, { allow: true, reasons: base.allowReasons }), input: base.input });
    for (const p of PERTURBATIONS) {
      const input = p.apply(base.input, catalogue);
      if (input === null) continue;
      const e = base.traits.alwaysAvailable ? ALLOW : p.expect(base.traits);
      const tags = base.traits.alwaysAvailable ? uniqTags(["SAFE-02"], p.tags) : uniqTags(p.tags, base.tags);
      probes.push({
        id: `authz.${base.key}.${p.key}`,
        entrypoint: "authz",
        description: `${base.description}; ${p.description}`,
        tags,
        expected: authzExpectation(catalogue, input.action, e.allow ? { allow: true, reasons: base.allowReasons } : { allow: false, reasons: e.reasons }),
        input,
      });
    }
  }
  for (const c of EXPLICIT) {
    probes.push({ id: `authz.explicit.${c.key}`, entrypoint: "authz", description: c.description, tags: c.tags, expected: authzExpectation(catalogue, c.input.action, c.expect), input: c.input });
  }
  for (const b of CONSOLE_BASES) {
    let base = consoleReq(b.action, b.allowedRole, b.resource ?? {});
    if (b.breakGlass) base = withBg(base, VALID_BREAK_GLASS);
    const allowReasons = b.allowReasons ?? ["ALLOW_STAFF_ROLE"];
    probes.push({ id: `console.${b.key}.base`, entrypoint: "console", description: `${b.action} by ${b.allowedRole}`, tags: b.tags, expected: consoleExpectation(catalogue, b.action, { allow: true, reasons: allowReasons }), input: base });
    if (b.deniedRole !== null) {
      const other = consoleReq(b.action, b.deniedRole, b.resource ?? {});
      probes.push({
        id: `console.${b.key}.role_${b.deniedRole}`,
        entrypoint: "console",
        description: `${b.action} by ${b.deniedRole} (role separation)`,
        tags: uniqTags(["SPEC-7.staff-separation"], b.tags),
        expected: consoleExpectation(catalogue, b.action, { allow: false, reasons: b.deniedReasons }),
        input: b.breakGlass ? withBg(other, VALID_BREAK_GLASS) : other,
      });
    }
    for (const p of CONSOLE_PERTURBATIONS) {
      probes.push({
        id: `console.${b.key}.${p.key}`,
        entrypoint: "console",
        description: `${b.action} by ${b.allowedRole}; ${p.description}`,
        tags: uniqTags(p.tags, b.tags),
        expected: consoleExpectation(catalogue, b.action, { allow: false, reasons: p.reasons }),
        input: p.apply(base),
      });
    }
  }
  for (const c of CONSOLE_EXPLICIT) {
    probes.push({ id: `console.explicit.${c.key}`, entrypoint: "console", description: c.description, tags: c.tags, expected: consoleExpectation(catalogue, c.input.action, c.expect), input: c.input });
  }
  return probes;
}

export function buildProbeFile(catalogue: PolicyCatalogue, policyVersion: string): GoldenProbeFile {
  const probes = generateProbes(catalogue);
  return { schemaVersion: 1, label: GOLDEN_LABEL, generator: GOLDEN_GENERATOR, generatedForPolicyVersion: policyVersion, probeCount: probes.length, probes };
}
